package qoder

// SideQuestionHistoryEntry is one prior Q/A pair passed to
// Client.SideQuestion for local context. Entries and their answers never
// enter the main conversation.
type SideQuestionHistoryEntry struct {
	Question string
	Response string
	// FallbackNotice is an optional note surfaced alongside the response.
	FallbackNotice string
}

// SideQuestionRefusalFallback describes an answer regenerated by a fallback
// model after the primary model refused.
type SideQuestionRefusalFallback struct {
	OriginalModel string
	FallbackModel string
	Content       string
}

// SideQuestionResult is the outcome of a side question. A nil result means
// the CLI produced no answer (the main turn keeps running regardless).
type SideQuestionResult struct {
	Response  string
	Synthetic bool
	// RefusalFallback is set when the answer came from a fallback model.
	RefusalFallback *SideQuestionRefusalFallback
}

// sideQuestionResultFromWire decodes the CLI response payload.
func sideQuestionResultFromWire(data map[string]any) *SideQuestionResult {
	if data == nil {
		return nil
	}
	res := &SideQuestionResult{
		Response:  str(data, "response"),
		Synthetic: boolVal(data, "synthetic"),
	}
	if fb, ok := data["refusal_fallback"].(map[string]any); ok {
		res.RefusalFallback = &SideQuestionRefusalFallback{
			OriginalModel: str(fb, "original_model"),
			FallbackModel: str(fb, "fallback_model"),
			Content:       str(fb, "content"),
		}
	}
	return res
}
